MIME-Version: 1.0
Content-Type: multipart/mixed; boundary="boundary-ai-1"

--boundary-ai-1
Content-Type: text/javascript; charset=utf-8
Content-Disposition: attachment; filename="fluid.demos.ai.imageGeneratorNearNotes"
Content-Description: layer

fluid.def("fluid.demos.ai.imageGeneratorNearNotes", {
    $layers: ["fluid.demos.imageGenerator", "fluid.topLevelWidget"],
    // Supplies the text of the sticky note closest to wherever the widget now sits, as the prompt for the image
    // generator - the user just moves the widget near a note and presses "Find Image"
    finder: {
        $component: {
            $layers: "fluid.demos.closestNoteFinder",
            view: "{imageGeneratorNearNotes}.view"
        }
    },
    state: {
        prompt: "{finder}.closest.text"
    }
});
--boundary-ai-1
Content-Type: multipart/mixed; boundary="boundary-ai-2"
Content-Disposition: attachment; filename="shape:noteImageGen"
Content-Description: component

--boundary-ai-2
Content-Type: application/json; charset=utf-8
Content-Disposition: attachment; filename="/"
Content-Description: potentia

{
    "$layers": [
        "fluid.demos.ai.imageGeneratorNearNotes"
    ],
    "view": {
        "$component": {
            "shapeId": "shape:noteImageGen"
        }
    }
}
--boundary-ai-2
